const {realVar, vectorVar, vec} = Symbolic;
const {fitData} = DataScience;
const trainXs = NArray.range(0, 500).map(i => [2 * Math.random() - 1, 2 * Math.random() - 1]);
const testXs = NArray.range(0, 2000).map(i => [2 * Math.random() - 1, 2 * Math.random() - 1]);
const yf = ([x, y]) => 2 * x * x - y * y + x * y + 0.5 + 0.3 * (2 * Math.random() - 1)
let {scene} = IO.plotPointCloud(trainXs.map(([x,y]) => [x, y, yf([x,y])]))
const x = realVar("x", true)
const y = realVar("y", true)
const a = vectorVar("a", 6)
const f = vec(1, x, y, x.mul(x), x.mul(y), y.mul(y)).dot(a)
const { compiledModel, theta} = fitData(trainXs, trainXs.map(p => yf(p)), f, {epochs: 2000, batch: 20})
IO.plotPointCloud(testXs.map(([xi,yi]) => [xi, yi, compiledModel({x: xi, y: yi, ...theta})]), {scene, color:[0,0,1]})
